function parseList(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.dm5.com').replace(/\/$/, '');
  var h = (typeof html === 'string') ? html : '';
  if (!h || h.length < 50) return [];
  function abs(u) {
    if (!u) return '';
    u = String(u).replace(/['"]/g, '').trim();
    if (u.indexOf('//') === 0) return 'https:' + u;
    if (u.indexOf('/') === 0) return baseUrl + u;
    return u;
  }
  function clean(s) { return String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); }
  function idOf(u) { return u.replace(/^\//, '').replace(/\/$/, ''); }
  var out = [], seen = {};
  function push(href, title, cover) {
    if (!href || href.indexOf('/manhua-') !== 0) return;
    if (seen[href]) return;
    if (!title) return;
    seen[href] = 1;
    out.push({ id: idOf(href), title: title, cover: abs(cover), detailUrl: baseUrl + href });
  }

  // A) 列表/分类/首页: <div class="mh-item ..."> ... </div></li>
  var itemRe = /<div[^>]*class="[^"]*\bmh-item\b[^"]*"[^>]*>([\s\S]*?)?<\/div>\s*<\/li>/gi;
  var m;
  while ((m = itemRe.exec(h)) !== null) {
    var b = m[1] || '';
    var cover = '';
    var bg = b.match(/class="[^"]*\bmh-cover\b[^"]*"[^>]*style="[^"]*background-image\s*:\s*url\(([^)]+)\)/i);
    if (bg) cover = bg[1];
    if (!cover) {
      var im = b.match(/<img[^>]*?(?:src|data-src|data-original)=["']([^"']+)["']/i);
      if (im) cover = im[1];
    }
    var a = b.match(/<a[^>]*href="(\/manhua-[^"]*)"[^>]*title="([^"]*)"[^>]*>/i);
    var title = '', href = '';
    if (a) { href = a[1]; title = (a[2] || '').trim(); }
    if (!title) {
      var a2 = b.match(/<a[^>]*href="(\/manhua-[^"]*)"[^>]*>([\s\S]*?)<\/a>/i);
      if (a2) { href = a2[1]; title = clean(a2[2]); }
    }
    push(href, title, cover);
  }

  // B) 搜索: <div class="banner_detail_form"> 中的 .cover img + p.title a
  if (out.length === 0) {
    var covers = [];
    var coverRe = /class="cover">\s*<img[^>]*?(?:src|data-src|data-original)=["']([^"']+)["']/gi;
    while ((m = coverRe.exec(h)) !== null) covers.push(m[1]);
    var tRe = /class="title">\s*<a[^>]*href="(\/manhua-[^"]+)"[^>]*title="([^"]*)"[^>]*>/gi;
    var ti = 0, tm;
    while ((tm = tRe.exec(h)) !== null) {
      push(tm[1], (tm[2] || '').trim(), covers[ti] || '');
      ti++;
    }
  }

  // C) 兜底: <a href="/manhua-..."> 内含图片
  if (out.length === 0) {
    var aRe = /<a\s+([^>]*?)href="(\/manhua-[^"]+)"([^>]*)>([\s\S]*?)<\/a>/gi;
    while ((m = aRe.exec(h)) !== null) {
      var href2 = m[2];
      if (seen[href2]) continue;
      var imgM = m[0].match(/<img[^>]*?(?:src|data-src|data-original)=["']([^"']+)["']/i);
      if (!imgM) continue;
      var t = clean(m[4]);
      if (!t) { var alt = m[0].match(/<img[^>]*?alt=["']([^"']+)["']/i); if (alt) t = alt[1].trim(); }
      if (!t) continue;
      push(href2, t, imgM[1]);
    }
  }
  return out;
}

