detail.script:
function parseDetail(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.dm5.com').replace(/\/$/, '');
  if (!html || typeof html !== 'string') html = '';
  var stripTags = function(s) { return String(s || '').replace(/<[^>]+>/g, '').replace(/\\s+/g, ' ').replace(/\u0020+/g, ' ').trim(); };
  var abs = function(u) { if (!u) return ''; u = String(u).trim(); if (u.indexOf('//') === 0) return 'https:' + u; if (u.indexOf('/') === 0) return baseUrl + u; return u; };

  var title = '';
  var mName = html.match(/var\s+DM5_COMIC_MNAME\s*=\s*["']([^"']+)["']/i);
  if (mName) title = mName[1].trim();
  if (!title) {
    // <p class="title">..text..<span class="right">..score..</span></p>
    var p = html.match(/<p\s+class=["']title["'][^>]*>([\s\S]*?)<span\s+class=["']right["']/i);
    if (p) title = p[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  }
  if (!title) {
    var og = html.match(/<meta[^>]*property=["']og:title["'][^>]*content=["']([^"']+)["']/i);
    if (og) title = og[1];
  }
  if (!title) {
    var h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    if (h1) title = stripTags(h1[1]);
  }
  if (!title) {
    var t = html.match(/<title>([\s\S]*?)<\/title>/i);
    if (t) title = t[1].replace(/漫画.*/, '').replace(/_.*/, '').replace(/动漫屋.*/, '').trim();
  }

  var cover = '';
  var coverM = html.match(/<div\s+class=["']cover["']>\s*<img[^>]*?(?:src|data-src|data-original)=["']([^"']+)["']/i)
      || html.match(/class=["']mh-cover["'][^>]*style=["'][^"']*background-image\s*:\s*url\(([^)]+)\)/i)
      || html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i);
  if (coverM) cover = abs(coverM[1].replace(/['"]/g, '').trim());

  var description = '';
  var descMeta = html.match(/<meta[^>]*?name=["']Description["'][^>]*?content=["']([^"']*?)["'][^>]*?>/i)
      || html.match(/<meta[^>]*?content=["']([^"']*?)["'][^>]*?name=["']Description["'][^>]*?>/i);
  if (descMeta) description = stripTags(descMeta[1]);
  // dm5 详情页简介以「漫画简介：」开头，取出冒号后正文
  var intro = description.match(/漫画简介[：:]\s*([\s\S]+)/);
  if (intro) description = intro[1].trim();
  else if (description && description.indexOf('提供') === 0) {
    var seg = description.split('。');
    description = seg.slice(1).join('。').trim();
  }

  var author = '';
  var aMatch = html.match(/作者\s*[：:]\s*(?:<a[^>]*>)?([^<]{1,40})/i);
  if (aMatch) author = aMatch[1].trim();

  var status = '';
  var stMatch = html.match(/状态\s*[：:]\s*(?:<\/?span[^>]*>)*\s*([^<\/\s][^<\/\n]{0,10})/i);
  if (stMatch) status = stMatch[1].trim();
  if (!status) {
    var c = html.match(/(连载中|已完结|完结)/i);
    if (c) status = c[1];
  }

  var tags = [];
  var tagUrls = [];
  var tagRe = /href="(\/manhua-[a-z]+\/)">\s*<span>([^<]+)<\/span>\s*<\/a>/gi;
  var tm;
  while ((tm = tagRe.exec(html)) !== null) {
    var tu = tm[1];
    var tn = (tm[2] || '').trim();
    if (tn && tags.indexOf(tn) === -1) {
      tags.push(tn);
      tagUrls.push(abs(tu));
    }
  }

  var score = '';
  var sc = html.match(/class=["']score["']>\s*([\d.]+)\s*分/);
  if (sc) score = sc[1];

  var slug = '';
  var slugM = html.match(/var\s+DM5_COMIC_URL\s*=\s*["']\/(manhua-[^"'\/]+)\//i)
      || html.match(/\/manhua-([^\/"' \s]+)\//);
  if (slugM) slug = slugM[1];

  return {
    title: title,
    coverUrl: cover,
    author: author,
    description: description,
    status: status,
    tags: tags,
    tagUrls: tagUrls,
    score: score,
    slug: slug
  };
}

chapters.script:
function parseChapters(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.dm5.com').replace(/\/$/, '');
  if (!html || typeof html !== 'string' || html.length < 50) return [];
  var results = [];
  var seen = {};
  var chapterRe = /<a\s+([^>]*)href="(\/[^"]+)"([^>]*)>([\s\S]*?)<\/a>/gi;
  var match;
  while ((match = chapterRe.exec(html)) !== null) {
    var href = match[2];
    var block = match[4];
    if (!/^\/m\d/.test(href)) continue; // 仅匹配 /m开头+数字 的章节地址，排除 /manhua-<目錄>
    if (seen[href]) continue;
    var title = block.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
    if (!title || title.length < 1) continue;
    if (/^(开始阅读|收藏|分享|立即阅读)$/.test(title)) continue;
    seen[href] = 1;
    var fullUrl = href.indexOf('http') === 0 ? href : baseUrl + href;
    results.push({ id: href.replace(/\//g, ''), title: title, url: fullUrl, updatedAt: '' });
  }
  return results;
}

images.script:
function parseImages(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.dm5.com').replace(/\/$/, '');
  var h = (typeof html === 'string') ? html : '';
  if (!h || h.length < 50) return [];
  // 从阅读页内嵌变量抽出签名参数（dm5 图片为 JS 签名动态加载，HTML 本体不含图）
  function grabStr(name) {
    var m = h.match(new RegExp('var\\s+' + name + '\\s*=\\s*"([^"]+)"'));
    return m ? m[1] : '';
  }
  function grabNum(name) {
    var m = h.match(new RegExp('var\\s+' + name + '\\s*=\\s*(\\d+)'));
    return m ? m[1] : '';
  }
  var cid = grabNum('DM5_CID');
  var mid = grabNum('DM5_MID');
  var viewsign = grabStr('DM5_VIEWSIGN');
  var viewsigndt = grabStr('DM5_VIEWSIGN_DT');
  var count = parseInt(grabNum('DM5_IMAGE_COUNT'), 10) || 0;
  // 部分章节的防热链 key 放在隐藏输入 #dm5_key；为空也兼容（接口允许）
  var key = '';
  var kM = h.match(/id=["']dm5_key["'][^>]*value=["']([^"']*)["']/i);
  if (kM) key = kM[1];
  if (!cid || !viewsign || !viewsigndt || count < 1) return [];
  var urls = [];
  for (var i = 1; i <= count; i++) {
    urls.push(baseUrl + '/chapterfun.ashx?cid=' + cid +
      '&page=' + i +
      '&key=' + encodeURIComponent(key) +
      '&language=1&gtk=6' +
      '&_cid=' + cid +
      '&_mid=' + mid +
      '&_dt=' + encodeURIComponent(viewsigndt) +
      '&_sign=' + viewsign);
  }
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchConcurrency: 8,
    __fetchResponseType: 'text',
    __processor: '__processDm5Images'
  };
}
function __processDm5Images(pages, context) {
  // pages 为接口原始 JS（packer 压缩包）；eval 后返回该页图片数组（arr）
  var out = [];
  for (var i = 0; i < pages.length; i++) {
    var r = pages[i];
    if (!r || typeof r !== 'string' || r.length < 10) continue;
    var arr = null;
    try { arr = eval(r); } catch (e) { arr = null; }
    if (arr && typeof arr === 'object' && arr.length) {
      for (var j = 0; j < arr.length; j++) {
        var u = arr[j];
        if (u && typeof u === 'string' && out.indexOf(u) === -1) out.push(u);
      }
    }
  }
  return out;
}
